class Solution:
    def multiply(self, num1, num2):
        if num1 == "0" or num2 == "0":
            return "0"

        m, n = len(num1), len(num2)
        result = [0] * (m + n)

        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                k = i + j + 1
                total = result[k] + (ord(num1[i]) - ord('0')) * (ord(num2[j]) - ord('0'))
                result[k] = total % 10
                result[k - 1] += total // 10

        start = 0
        while start < len(result) - 1 and result[start] == 0:
            start += 1

        return ''.join(str(digit) for digit in result[start:])

code.C:
#include <stdlib.h>
#include <string.h>

char* multiply(char* num1, char* num2) {
    if (strcmp(num1, "0") == 0 || strcmp(num2, "0") == 0) {
        char* zero = (char*)malloc(2 * sizeof(char));
        zero[0] = '0';
        zero[1] = '\0';
        return zero;
    }

    int m = (int)strlen(num1);
    int n = (int)strlen(num2);
    int* result = (int*)calloc((size_t)(m + n), sizeof(int));

    for (int i = m - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            int k = i + j + 1;
            int total = result[k]
                      + (num1[i] - '0') * (num2[j] - '0');
            result[k] = total % 10;
            result[k - 1] += total / 10;
        }
    }

    int start = 0;
    while (start < m + n - 1 && result[start] == 0) {
        ++start;
    }

    char* answer = (char*)malloc((size_t)(m + n - start + 1) * sizeof(char));
    int pos = 0;
    for (int i = start; i < m + n; ++i) {
        answer[pos++] = (char)('0' + result[i]);
    }
    answer[pos] = '\0';

    free(result);
    return answer;
}

code.C++:
class Solution {
public:
    string multiply(string num1, string num2) {
        if (num1 == "0" || num2 == "0") {
            return "0";
        }

        int m = (int)num1.size();
        int n = (int)num2.size();
        vector<int> result(m + n, 0);

        for (int i = m - 1; i >= 0; --i) {
            for (int j = n - 1; j >= 0; --j) {
                int k = i + j + 1;
                int total = result[k]
                          + (num1[i] - '0') * (num2[j] - '0');
                result[k] = total % 10;
                result[k - 1] += total / 10;
            }
        }

        int start = 0;
        while (start < m + n - 1 && result[start] == 0) {
            ++start;
        }

        string answer;
        answer.reserve(m + n - start);
        for (int i = start; i < m + n; ++i) {
            answer.push_back((char)('0' + result[i]));
        }
        return answer;
    }
}

