class Solution {
    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";
        }

        int m = num1.length();
        int n = num2.length();
        int[] result = new int[m + n];

        for (int i = m - 1; i >= 0; --i) {
            for (int j = n - 1; j >= 0; --j) {
                int k = i + j + 1;
                int total = result[k]
                        + (num1.charAt(i) - '0') * (num2.charAt(j) - '0');
                result[k] = total % 10;
                result[k - 1] += total / 10;
            }
        }

        int start = 0;
        while (start < result.length - 1 && result[start] == 0) {
            ++start;
        }

        StringBuilder answer = new StringBuilder(result.length - start);
        for (int i = start; i < result.length; ++i) {
            answer.append((char) ('0' + result[i]));
        }
        return answer.toString();
    }
}

