/**
 * @param {string} num1
 * @param {string} num2
 * @return {string}
 */
var multiply = function(num1, num2) {
    if (num1 === "0" || num2 === "0") {
        return "0";
    }

    const m = num1.length;
    const n = num2.length;
    const result = new Array(m + n).fill(0);

    for (let i = m - 1; i >= 0; --i) {
        for (let j = n - 1; j >= 0; --j) {
            const k = i + j + 1;
            const total = result[k]
                + (num1.charCodeAt(i) - 48) * (num2.charCodeAt(j) - 48);
            result[k] = total % 10;
            result[k - 1] += Math.floor(total / 10);
        }
    }

    let start = 0;
    while (start < result.length - 1 && result[start] === 0) {
        ++start;
    }

    return result.slice(start).join("");
};

